/**
 * syno_markdown —— Markdown 输入即转换 + 粘贴识别转换
 * 目标环境：Synology Note Station Client / TinyMCE 4.5.7
 *
 * 设计原则：
 *   1. 只做「输入侧」转换，笔记存储格式仍是 Note Station 原生 HTML，
 *      同步、手机端、AI、导出全部不受影响。
 *   2. 仅当当前块内容「恰好等于」标记时才转换，避免误伤正文。
 *   3. 所有改动走 undoManager.transact，Cmd+Z 可回退。
 *   4. 工具栏 MD 按钮可随时关闭，状态存 localStorage。
 *
 * 一、输入即转换（行首 + 空格触发）：
 *    # ~ ######        -> 标题 1~6
 *    - / * / +         -> 无序列表
 *    1.                -> 有序列表
 *    >                 -> 引用块
 *    - [ ] / [ ]       -> Note Station 原生待办复选框
 *    ---               -> 分隔线
 *    ```               -> 代码块
 *
 * 二、行内语法（输入结束定界符时立即转换）：
 *    **粗体**  *斜体*  _斜体_  ~~删除线~~  `行内代码`
 *
 * 三、粘贴识别转换（剪贴板纯文本判定为 Markdown 时自动渲染成富文本）：
 *    标题 / 无序有序列表（含嵌套）/ 任务列表 / 引用（可嵌套）/ 围栏代码块 /
 *    水平线 / GFM 表格 / 粗体 斜体 删除线 行内代码 / 链接 / 图片
 *    逃生通道：按住 Option(Alt) 粘贴 = 按原样粘贴不转换；Cmd+Z 撤销。
 */
tinymce.PluginManager.add('syno_markdown', function (editor) {
    'use strict';

    var STORAGE_KEY = 'syno_markdown_enabled';
    var BLOCK_SELECTOR = 'div,p,h1,h2,h3,h4,h5,h6,li,blockquote,pre,td,th';

    /** 读取开关状态，默认开启 */
    function readEnabled() {
        try {
            var v = window.localStorage.getItem(STORAGE_KEY);
            return v === null ? true : v === '1';
        } catch (e) {
            return true;
        }
    }

    function persist() {
        try {
            window.localStorage.setItem(STORAGE_KEY, enabled ? '1' : '0');
        } catch (e) {
            /* localStorage 不可用时忽略 */
        }
    }

    var enabled = readEnabled();

    /** 取光标所在块级元素 */
    function currentBlock() {
        var node = editor.selection.getStart();
        if (!node) {
            return null;
        }
        return editor.dom.getParent(node, BLOCK_SELECTOR);
    }

    /** 清空块内文本，并把光标留在块内 */
    function clearBlock(block) {
        var range = document.createRange();
        range.selectNodeContents(block);
        range.deleteContents();
        editor.selection.setRng(range);
    }

    /** 把光标放到元素之后 */
    function caretAfter(el) {
        var range = document.createRange();
        var parent = el.parentNode;
        var index = Array.prototype.indexOf.call(parent.childNodes, el);
        range.setStart(parent, index + 1);
        range.collapse(true);
        editor.selection.setRng(range);
    }

    /** 触发一次内容变更通知与 undo 记录 */
    function touch() {
        editor.undoManager.add();
        editor.nodeChanged();
    }

    // =====================================================================
    //  一、输入即转换
    // =====================================================================

    /** 行首标记 -> 块级格式 */
    function blockRule() {
        var sel = editor.selection;
        if (!sel.isCollapsed()) {
            return false;
        }
        var block = currentBlock();
        if (!block) {
            return false;
        }
        var tag = block.nodeName.toLowerCase();
        // 列表项、代码块、表格单元格内部不再做块级转换
        if (tag === 'li' || tag === 'pre' || tag === 'td' || tag === 'th') {
            return false;
        }
        var text = (block.textContent || '').replace(/\u00a0/g, ' ').replace(/\s+$/, '');
        if (!text) {
            return false;
        }

        var m;

        // 标题 # ~ ######
        if ((m = /^(#{1,6})$/.exec(text))) {
            var level = m[1].length;
            editor.undoManager.transact(function () {
                clearBlock(block);
                editor.formatter.apply('h' + level);
            });
            touch();
            return true;
        }

        // 引用块 >
        if (text === '>') {
            editor.undoManager.transact(function () {
                var quote = editor.dom.create('blockquote');
                var line = editor.dom.create('div');
                quote.appendChild(line);
                block.parentNode.replaceChild(quote, block);
                editor.selection.setCursorLocation(line, 0);
            });
            touch();
            return true;
        }

        // 待办复选框 - [ ] / [ ]
        if (text === '- [ ]' || text === '[ ]' || text === '- []' || text === '[]') {
            editor.undoManager.transact(function () {
                clearBlock(block);
                editor.execCommand('syno_checkbox_insert');
            });
            touch();
            return true;
        }

        // 分隔线 ---
        if (/^(-{3,}|\*{3,}|_{3,})$/.test(text)) {
            editor.undoManager.transact(function () {
                clearBlock(block);
                editor.execCommand('InsertHorizontalRule');
            });
            touch();
            return true;
        }

        // 代码块 ```
        if (text === '```') {
            editor.undoManager.transact(function () {
                var pre = editor.dom.create('pre');
                var code = editor.dom.create('code');
                code.appendChild(editor.getDoc().createTextNode('\u00a0'));
                pre.appendChild(code);
                block.parentNode.replaceChild(pre, block);
                editor.selection.setCursorLocation(code, 0);
            });
            touch();
            return true;
        }

        // 无序列表 - / * / +
        if (/^[-*+]$/.test(text)) {
            editor.undoManager.transact(function () {
                clearBlock(block);
                editor.execCommand('InsertUnorderedList');
            });
            touch();
            return true;
        }

        // 有序列表 1.
        if (/^\d+\.$/.test(text)) {
            editor.undoManager.transact(function () {
                clearBlock(block);
                editor.execCommand('InsertOrderedList');
            });
            touch();
            return true;
        }

        return false;
    }

    /**
     * 行内标记转换
     * @param {string} ch 刚输入的字符
     */
    function inlineRule(ch) {
        if (ch !== '*' && ch !== '_' && ch !== '~' && ch !== '`') {
            return false;
        }
        var sel = editor.selection;
        if (!sel.isCollapsed()) {
            return false;
        }
        var range = sel.getRng();
        var node = range.startContainer;
        if (!node || node.nodeType !== 3) {
            return false;
        }
        // 代码块、行内代码里不转换
        if (editor.dom.getParent(node, 'pre,code')) {
            return false;
        }

        var offset = range.startOffset;
        var left = node.data.slice(0, offset);
        var specs = [
            { re: /\*\*([\s\S]*?)\*\*$/, el: 'strong' },
            { re: /__([\s\S]*?)__$/, el: 'strong' },
            { re: /~~([\s\S]*?)~~$/, el: 'del' },
            { re: /`([\s\S]*?)`$/, el: 'code' },
            { re: /\*([\s\S]*?)\*$/, el: 'em' },
            { re: /_([\s\S]*?)_$/, el: 'em' }
        ];

        for (var i = 0; i < specs.length; i++) {
            var spec = specs[i];
            var m = spec.re.exec(left);
            if (!m) {
                continue;
            }
            var content = m[1];
            // 空内容不转换；内容里含定界符残留也不转换
            if (!content || !content.replace(/\s/g, '')) {
                continue;
            }
            var start = offset - m[0].length;
            if (start > 0 && left.charAt(start - 1) === '\\') {
                return false;
            }
            editor.undoManager.transact(function () {
                var after = node.splitText(offset);
                var mid = node.splitText(start);
                var wrapper = editor.dom.create(spec.el);
                wrapper.textContent = content;
                mid.parentNode.replaceChild(wrapper, mid);
                caretAfter(wrapper);
                if (!after.data) {
                    /* 保留光标位置即可 */
                }
            });
            touch();
            return true;
        }
        return false;
    }

    editor.on('keyup', function (e) {
        if (!enabled) {
            return;
        }
        var key = e.key;
        if (key === ' ') {
            blockRule();
            return;
        }
        if (key && key.length === 1) {
            inlineRule(key);
        }
    });

    // =====================================================================
    //  二、Markdown -> HTML 渲染
    // =====================================================================

    function escapeHtml(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    // Note Station 原生待办复选框资源（相对页面 URL，与 syno_checkbox 插件一致）
    var CB_DIR = 'webman/modules/TinyMCE/js/tinymce/plugins/syno_checkbox';
    var CB_OFF = CB_DIR + '/editor_checkbox_01.png';
    var CB_ON = CB_DIR + '/editor_checkbox_03.png';
    var CB_BLANK = 'webman/3rdparty/NoteStation/images/transparent.gif';
    var CB_CLASS = 'syno-notestation-editor-checkbox';
    var CB_CLASS_ON = 'syno-notestation-editor-checkbox-checked';

    function checkboxHtml(checked) {
        return '<input type="image" src="' + (checked ? CB_ON : CB_OFF) + '"'
            + ' data-mce-src="' + CB_BLANK + '"'
            + ' class="' + CB_CLASS + (checked ? ' ' + CB_CLASS_ON : '') + '">';
    }

    var RE_IMG = /!\[([^\]]*)\]\(\s*<?([^\s)>]+)>?(?:\s+(?:"([^"]*)"|'([^']*)'))?\s*\)/g;
    var RE_LINK = /\[([^\]\n]*)\]\(\s*<?([^\s)>]+)>?(?:\s+(?:"([^"]*)"|'([^']*)'))?\s*\)/g;
    var RE_CODE_SPAN = /(`+)([^`]|[^`][\s\S]*?[^`])\1(?!`)/g;
    var RE_ESCAPE_CH = /\\([\\`*_{}\[\]()#+\-.!~>|])/g;
    var RE_PLACEHOLDER = /\u0001(\d+)\u0002/g;

    /**
     * 行内语法渲染
     * @param {string} text 单行 Markdown 文本
     * @returns {string} HTML
     */
    function renderInline(text) {
        var stash = [];
        function keep(html) {
            stash.push(html);
            return '\u0001' + (stash.length - 1) + '\u0002';
        }

        var s = String(text == null ? '' : text);

        // 1) 反斜杠转义
        s = s.replace(RE_ESCAPE_CH, function (m, ch) {
            return keep(escapeHtml(ch));
        });

        // 2) 行内代码（内容不再参与后续解析）
        s = s.replace(RE_CODE_SPAN, function (m, ticks, body) {
            return keep('<code>' + escapeHtml(body.replace(/^ | $/g, '')) + '</code>');
        });

        // 3) 图片（先于链接，避免 ![a](b) 被链接规则吃掉）
        s = s.replace(RE_IMG, function (m, alt, url, t1, t2) {
            var title = t1 || t2 || '';
            return keep('<img src="' + escapeHtml(url) + '" alt="' + escapeHtml(alt) + '"'
                + (title ? ' title="' + escapeHtml(title) + '"' : '') + '>');
        });

        // 4) 链接（文本递归渲染，支持 [**粗**](url)）
        s = s.replace(RE_LINK, function (m, txt, url, t1, t2) {
            var title = t1 || t2 || '';
            return keep('<a href="' + escapeHtml(url) + '" target="_blank"'
                + (title ? ' title="' + escapeHtml(title) + '"' : '') + '>'
                + renderInline(txt) + '</a>');
        });

        // 5) 剩余裸文本整体转义
        s = escapeHtml(s);

        // 6) 强调
        s = s.replace(/\*\*(?=\S)([\s\S]*?\S)\*\*/g, '<strong>$1</strong>');
        s = s.replace(/__(?=\S)([\s\S]*?\S)__/g, '<strong>$1</strong>');
        s = s.replace(/~~(?=\S)([\s\S]*?\S)~~/g, '<del>$1</del>');
        s = s.replace(/(^|[^*])\*(?=\S)([^*\n]*?\S)\*(?!\*)/g, '$1<em>$2</em>');
        s = s.replace(/(^|[^A-Za-z0-9_])_(?=\S)([^_\n]*?\S)_(?![A-Za-z0-9_])/g, '$1<em>$2</em>');

        // 7) 还原占位符
        for (var pass = 0; pass < 6 && s.indexOf('\u0001') !== -1; pass++) {
            s = s.replace(RE_PLACEHOLDER, function (m, n) {
                return stash[+n] != null ? stash[+n] : m;
            });
        }
        return s;
    }

    /** 多行文本逐行渲染，行间用 <br> */
    function renderInlineLines(text) {
        return String(text == null ? '' : text)
            .split('\n')
            .map(function (line) { return renderInline(line.replace(/[ \t]+$/, '')); })
            .join('<br>');
    }

    var RE_LIST_ITEM = /^([ \t]*)([-*+]|\d{1,9}[.)])[ \t]+([\s\S]*)$/;
    var RE_FENCE_OPEN = /^([ \t]{0,3})(`{3,}|~{3,})[ \t]*([^`~]*)$/;
    var RE_ATX = /^[ \t]{0,3}(#{1,6})[ \t]+(.*?)[ \t]*#*[ \t]*$/;
    var RE_QUOTE = /^[ \t]{0,3}>/;
    var RE_HR = /^[ \t]{0,3}(?:(?:\*[ \t]*){3,}|(?:-[ \t]*){3,}|(?:_[ \t]*){3,})$/;
    var RE_TABLE_SEP = /^[ \t]{0,3}\|?[ \t]*:?-+:?[ \t]*(?:\|[ \t]*:?-+:?[ \t]*)+\|?[ \t]*$/;

    function indentWidth(line) {
        var m = /^[ \t]*/.exec(line)[0];
        return m.replace(/\t/g, '    ').length;
    }

    function isBlockStart(line) {
        return /^[ \t]*$/.test(line)
            || RE_FENCE_OPEN.test(line)
            || RE_ATX.test(line)
            || RE_QUOTE.test(line)
            || RE_HR.test(line)
            || RE_TABLE_SEP.test(line)
            || RE_LIST_ITEM.test(line);
    }

    /** 拆分表格行（支持 \| 转义） */
    function splitRow(line) {
        var s = line.trim();
        if (s.charAt(0) === '|') {
            s = s.slice(1);
        }
        if (s.length && s.charAt(s.length - 1) === '|' && s.charAt(s.length - 2) !== '\\') {
            s = s.slice(0, -1);
        }
        var cells = [];
        var cur = '';
        var esc = false;
        for (var k = 0; k < s.length; k++) {
            var ch = s.charAt(k);
            if (esc) {
                cur += ch;
                esc = false;
                continue;
            }
            if (ch === '\\') {
                esc = true;
                continue;
            }
            if (ch === '|') {
                cells.push(cur);
                cur = '';
                continue;
            }
            cur += ch;
        }
        cells.push(cur);
        return cells.map(function (c) { return c.trim(); });
    }

    /** 解析列表块（支持缩进嵌套） */
    function parseList(lines, start) {
        var first = RE_LIST_ITEM.exec(lines[start]);
        var baseIndent = first[1].replace(/\t/g, '    ').length;
        var ordered = /^\d/.test(first[2]);
        var items = [];
        var i = start;

        while (i < lines.length) {
            var line = lines[i];

            if (/^[ \t]*$/.test(line)) {
                // 空行：后面若仍是同级/更深的列表项则继续（松散列表）
                var j = i + 1;
                while (j < lines.length && /^[ \t]*$/.test(lines[j])) {
                    j++;
                }
                if (j >= lines.length) {
                    break;
                }
                var nm = RE_LIST_ITEM.exec(lines[j]);
                if (nm && nm[1].replace(/\t/g, '    ').length >= baseIndent
                    && /^\d/.test(nm[2]) === ordered) {
                    i = j;
                    continue;
                }
                if (items.length && indentWidth(lines[j]) > baseIndent) {
                    i = j;
                    continue;
                }
                break;
            }

            var m = RE_LIST_ITEM.exec(line);
            var ind = indentWidth(line);

            if (m && ind <= baseIndent + 1) {
                // 标记类型变化（- <-> 1.）= 另一个列表，交由外层重新开始
                if (/^\d/.test(m[2]) !== ordered) {
                    break;
                }
                items.push({ text: m[3], sub: [] });
                i++;
                continue;
            }
            if (items.length && ind > baseIndent) {
                items[items.length - 1].sub.push(line);
                i++;
                continue;
            }
            if (items.length) {
                // 惰性续行
                items[items.length - 1].text += '\n' + line.replace(/^[ \t]+/, '');
                i++;
                continue;
            }
            break;
        }

        var tag = ordered ? 'ol' : 'ul';
        var html = '<' + tag + '>';
        for (var k = 0; k < items.length; k++) {
            var it = items[k];
            var task = /^\[([ xX])\][ \t]+([\s\S]*)$/.exec(it.text);
            if (task) {
                var checked = task[1].toLowerCase() === 'x';
                html += '<li style="list-style:none">'
                    + checkboxHtml(checked) + ' '
                    + renderInlineLines(task[2]) + '</li>';
            } else {
                var sub = it.sub.length ? mdToHtml(it.sub.join('\n')) : '';
                html += '<li>' + renderInlineLines(it.text) + sub + '</li>';
            }
        }
        html += '</' + tag + '>';
        return { html: html, next: i };
    }

    /** 解析 GFM 表格 */
    function parseTable(lines, start) {
        var header = splitRow(lines[start]);
        var sep = splitRow(lines[start + 1]);
        var aligns = sep.map(function (c) {
            var l = c.charAt(0) === ':';
            var r = c.charAt(c.length - 1) === ':';
            return l && r ? 'center' : r ? 'right' : l ? 'left' : '';
        });

        var i = start + 2;
        var rows = [];
        while (i < lines.length && !/^[ \t]*$/.test(lines[i]) && lines[i].indexOf('|') !== -1) {
            rows.push(splitRow(lines[i]));
            i++;
        }

        // 表格样式：内联写死，保证编辑器 / DSM 网页 / 手机端显示一致
        // 配色取自 Note Station 自身色板（边框 #D7E1EB）
        var TBL_STYLE = 'border-collapse:collapse;width:100%;';
        var TH_BASE = 'border:1px solid #d7e1eb;background:#f2f6fa;padding:8px 12px;'
            + 'font-weight:bold;vertical-align:top;';
        var TD_BASE = 'border:1px solid #d7e1eb;padding:8px 12px;vertical-align:top;';
        var TR_ALT = 'background:#fafcfe;';

        function cellAttr(k, isHead) {
            var style = (isHead ? TH_BASE : TD_BASE);
            var al = aligns[k];
            if (al) {
                style += 'text-align:' + al + ';';
            }
            return (al ? ' align="' + al + '"' : '') + ' style="' + style + '"';
        }

        var html = '<table style="' + TBL_STYLE + '"><thead><tr>';
        for (var a = 0; a < header.length; a++) {
            html += '<th' + cellAttr(a, true) + '>' + renderInline(header[a]) + '</th>';
        }
        html += '</tr></thead><tbody>';
        for (var r = 0; r < rows.length; r++) {
            html += '<tr' + (r % 2 === 1 ? ' style="' + TR_ALT + '"' : '') + '>';
            for (var c = 0; c < header.length; c++) {
                html += '<td' + cellAttr(c, false) + '>'
                    + renderInline(rows[r][c] == null ? '' : rows[r][c]) + '</td>';
            }
            html += '</tr>';
        }
        html += '</tbody></table>';
        return { html: html, next: i };
    }

    /**
     * Markdown -> HTML
     * @param {string} src Markdown 源文本
     * @returns {string} HTML 片段
     */
    function mdToHtml(src) {
        var text = String(src == null ? '' : src).replace(/\r\n?/g, '\n').replace(/\t/g, '    ');
        var lines = text.split('\n');
        var out = [];
        var i = 0;
        var guard = 0;

        while (i < lines.length && guard++ < 200000) {
            var line = lines[i];

            // 空行
            if (/^[ \t]*$/.test(line)) {
                i++;
                continue;
            }

            // 围栏代码块
            var fm = RE_FENCE_OPEN.exec(line);
            if (fm) {
                var fenceChar = fm[2].charAt(0);
                var fenceLen = fm[2].length;
                var lang = (fm[3] || '').trim().split(/\s+/)[0];
                var buf = [];
                i++;
                var closeRe = new RegExp('^[ \\t]{0,3}' + (fenceChar === '`' ? '`' : '~')
                    + '{' + fenceLen + ',}[ \\t]*$');
                while (i < lines.length && !closeRe.test(lines[i])) {
                    buf.push(lines[i]);
                    i++;
                }
                if (i < lines.length) {
                    i++;
                }
                out.push('<pre' + (lang ? ' data-md-lang="' + escapeHtml(lang) + '"' : '') + '>'
                    + '<code>' + escapeHtml(buf.join('\n')) + '</code></pre>');
                continue;
            }

            // 水平线
            if (RE_HR.test(line)) {
                out.push('<hr>');
                i++;
                continue;
            }

            // ATX 标题
            var hm = RE_ATX.exec(line);
            if (hm) {
                var lv = hm[1].length;
                out.push('<h' + lv + '>' + renderInline(hm[2]) + '</h' + lv + '>');
                i++;
                continue;
            }

            // 引用块（可嵌套）
            if (RE_QUOTE.test(line)) {
                var qbuf = [];
                while (i < lines.length && RE_QUOTE.test(lines[i])) {
                    qbuf.push(lines[i].replace(/^[ \t]{0,3}>[ \t]?/, ''));
                    i++;
                }
                out.push('<blockquote>' + (mdToHtml(qbuf.join('\n')) || '<div><br></div>') + '</blockquote>');
                continue;
            }

            // 表格
            if (line.indexOf('|') !== -1 && i + 1 < lines.length && RE_TABLE_SEP.test(lines[i + 1])) {
                var tb = parseTable(lines, i);
                out.push(tb.html);
                i = tb.next;
                continue;
            }

            // 列表
            if (RE_LIST_ITEM.test(line)) {
                var ls = parseList(lines, i);
                out.push(ls.html);
                i = ls.next;
                continue;
            }

            // 段落
            var pbuf = [];
            while (i < lines.length && !isBlockStart(lines[i])) {
                pbuf.push(lines[i]);
                i++;
            }
            if (pbuf.length) {
                out.push('<div>' + pbuf.map(function (l) {
                    return renderInline(l.replace(/^[ \t]+/, ''));
                }).join('<br>') + '</div>');
            } else {
                i++;
            }
        }
        return out.join('');
    }

    // =====================================================================
    //  三、Markdown 识别（避免误判普通文本 / 代码）
    // =====================================================================

    var RE_T_FENCE = /^[ \t]{0,3}(?:`{3,}|~{3,})/m;
    var RE_T_ATX = /^[ \t]{0,3}#{1,6}[ \t]+\S/m;
    var RE_T_QUOTE = /^[ \t]{0,3}>[ \t]?\S/m;
    var RE_T_TASK = /^[ \t]{0,3}[-*+][ \t]+\[[ xX]\][ \t]+\S/m;
    var RE_T_HR = /^[ \t]{0,3}(?:(?:\*[ \t]*){3,}|(?:-[ \t]*){3,}|(?:_[ \t]*){3,})$/m;
    var RE_T_UL = /^[ \t]{0,3}[-*+][ \t]+\S/gm;
    var RE_T_OL = /^[ \t]{0,3}\d{1,9}[.)][ \t]+\S/gm;

    /** 粗判：这段文本更像代码而不是 Markdown 正文 */
    function looksLikeCode(s) {
        var lines = s.split('\n');
        var hits = 0;
        for (var i = 0; i < lines.length; i++) {
            var l = lines[i];
            if (/^ {2,}[\S]/.test(l)) {
                hits++;
            }
            if (/[;{}]\s*$/.test(l)) {
                hits++;
            }
            if (/^\s*(?:def|class|function|import|from|package|public|private|protected|const|let|var|return|if|for|while|switch|SELECT|INSERT|UPDATE|DELETE|CREATE)\b/.test(l)) {
                hits++;
            }
        }
        return hits >= Math.max(3, Math.floor(lines.length * 0.35));
    }

    /**
     * 判断剪贴板纯文本是否为 Markdown
     * @param {string} text 纯文本
     * @returns {boolean}
     */
    function looksLikeMarkdown(text) {
        if (!text || text.length > 300000) {
            return false;
        }
        var s = text.replace(/\r\n?/g, '\n');

        var hasFence = RE_T_FENCE.test(s);

        // 带围栏代码块的一律按 Markdown 处理
        if (hasFence) {
            return true;
        }
        // 像代码的（缩进 / 分号大括号 / 关键字行）不转换，避免把 # 注释当标题
        if (looksLikeCode(s)) {
            return false;
        }

        var strong = 0;
        var weak = 0;

        if (RE_T_ATX.test(s)) {
            strong += 2;
        }
        if (RE_T_TASK.test(s)) {
            strong += 3;
        }
        if (RE_T_QUOTE.test(s)) {
            strong += 2;
        }
        if (RE_T_HR.test(s)) {
            strong += 2;
        }
        // 表格：逐行找「含 | 的行 + 分隔行」
        var rows = s.split('\n');
        for (var r = 0; r + 1 < rows.length; r++) {
            if (rows[r].indexOf('|') !== -1 && RE_TABLE_SEP.test(rows[r + 1])) {
                strong += 3;
                break;
            }
        }

        var ul = (s.match(RE_T_UL) || []).length;
        if (ul >= 2) {
            strong += 2;
        } else if (ul === 1) {
            weak += 1;
        }
        var ol = (s.match(RE_T_OL) || []).length;
        if (ol >= 2) {
            strong += 2;
        } else if (ol === 1) {
            weak += 1;
        }

        // 行内信号
        if (/\*\*[^\s*][\s\S]*?[^\s*]\*\*/.test(s)) {
            weak += 1;
        }
        if (/~~[^\s~][\s\S]*?[^\s~]~~/.test(s)) {
            weak += 1;
        }
        if (/`[^`\n]+`/.test(s)) {
            weak += 1;
        }
        var links = (s.match(/\[[^\]\n]*\]\([^)\s]+\)/g) || []).length;
        if (links) {
            weak += Math.min(links, 2);
        }
        if (/!\[[^\]\n]*\]\([^)\s]+\)/.test(s)) {
            weak += 2;
        }

        return strong >= 2 || (strong >= 1 && strong + weak >= 3) || weak >= 4;
    }

    // =====================================================================
    //  四、粘贴接管
    // =====================================================================

    var pendingRng = null;
    var pendingAt = 0;

    /** 剪贴板 HTML 是否带真实排版（用于区分「富文本来源」与「纯文本的 HTML 包装」） */
    function htmlHasFormat(html) {
        return /<(strong|b|em|i|u|s|del|h[1-6]|ul|ol|li|table|thead|tbody|tr|td|th|blockquote|pre|img)\b/i.test(html)
            || /<a\s[^>]*href/i.test(html);
    }

    /** 粘贴前（捕获阶段）先记住光标位置：syno_paste 会把光标临时挪进粘贴缓冲 */
    function onKeyDownCapture(e) {
        var key = e.key || '';
        var isPasteKey = (e.metaKey || e.ctrlKey) && (key === 'v' || key === 'V' || e.keyCode === 86);
        if (!isPasteKey) {
            return;
        }
        try {
            pendingRng = editor.selection.getRng().cloneRange();
            pendingAt = Date.now();
        } catch (err) {
            pendingRng = null;
        }
    }

    function toast(msg) {
        try {
            if (editor.notificationManager && editor.notificationManager.open) {
                editor.notificationManager.open({ text: msg, type: 'success', timeout: 2600 });
            }
        } catch (e) {
            /* 皮肤不支持通知时静默 */
        }
    }

    /**
     * 让美化插件对「还没处理过」的代码块做一次自动格式化 + 语法高亮。
     * 美化插件未安装时静默跳过；已处理过的代码块带 data-nsh-lang 标记，不会重复改写。
     */
    function autoHighlightCode() {
        try {
            var polish = window.__synoHighlightCode;
            if (typeof polish !== 'function') {
                return;
            }
            var pres = editor.getBody().querySelectorAll('pre');
            for (var i = 0; i < pres.length; i++) {
                if (!pres[i].getAttribute('data-nsh-lang')) {
                    polish(pres[i]);
                }
            }
        } catch (e) {
            /* 高亮失败不影响粘贴结果 */
        }
    }

    /**
     * 粘贴进来的 ```mermaid 代码块交给 Mermaid 插件渲染成图。
     * 插件未安装时 window.__synoRenderMermaid 不存在，静默跳过。
     */
    function autoRenderMermaid() {
        try {
            var run = window.__synoRenderMermaid;
            if (typeof run === 'function') {
                run();
            }
        } catch (e) {
            /* 渲染失败不影响粘贴结果，代码块仍保留 */
        }
    }

    function onPasteCapture(e) {
        if (!enabled) {
            return;
        }
        // 按住 Option(Alt) 粘贴 = 强制按原样粘贴
        if (e.altKey) {
            return;
        }
        // 已处于代码块/行内代码内：保持原样
        try {
            if (editor.dom.getParent(editor.selection.getStart(), 'pre,code')) {
                return;
            }
            // 表格单元格内不转换：块级元素会破坏表格结构
            if (editor.dom.getParent(editor.selection.getStart(), 'td,th')) {
                return;
            }
        } catch (err) {
            return;
        }

        var cd = e.clipboardData || (editor.getDoc() && editor.getDoc().dataTransfer);
        if (!cd || typeof cd.getData !== 'function') {
            return;
        }

        var text;
        var clipHtml = '';
        try {
            text = cd.getData('text/plain') || cd.getData('Text') || '';
            clipHtml = cd.getData('text/html') || '';
        } catch (err) {
            return;
        }
        if (!text || !looksLikeMarkdown(text)) {
            return;
        }
        // 剪贴板同时带「真有格式」的 HTML（网页/Word/笔记内部复制）时，
        // 保留来源格式，不做 Markdown 转换
        if (clipHtml && htmlHasFormat(clipHtml)) {
            return;
        }

        var html;
        try {
            html = mdToHtml(text);
        } catch (err) {
            html = '';
        }
        if (!html) {
            return; // 渲染失败：交回原生粘贴
        }

        // 接管这次粘贴
        e.preventDefault();
        e.stopPropagation();
        if (typeof e.stopImmediatePropagation === 'function') {
            e.stopImmediatePropagation();
        }

        var rng = (pendingRng && Date.now() - pendingAt < 5000) ? pendingRng : null;
        pendingRng = null;

        var hasTask = html.indexOf(CB_CLASS) !== -1;

        // 延后一拍执行，确保浏览器已彻底放弃默认粘贴
        window.setTimeout(function () {
            try {
                // 清理 syno_paste 为快捷键粘贴预建的隐藏缓冲
                var doc = editor.getDoc();
                var pb = doc.getElementById('mcepastebin');
                if (pb && pb.parentNode) {
                    pb.parentNode.removeChild(pb);
                }
                if (rng) {
                    try {
                        editor.selection.setRng(rng);
                    } catch (e2) {
                        /* 原位置失效则用当前光标 */
                    }
                }
                editor.undoManager.transact(function () {
                    editor.insertContent(html, { merge: false });
                });
                editor.nodeChanged();

                // 粘贴出来的代码块：自动格式化 + 语法高亮
                autoHighlightCode();

                // ```mermaid 代码块：渲染成图（异步，不阻塞粘贴）
                autoRenderMermaid();

                // 待办复选框需要 syno_checkbox 重新绑定点击事件
                if (hasTask) {
                    try {
                        editor.fire('SetContent', { content: editor.getContent() });
                    } catch (e3) {
                        /* 忽略 */
                    }
                }
                toast('已按 Markdown 转换粘贴');
            } catch (err) {
                /* 静默失败，不影响正常编辑 */
            }
        }, 0);
    }

    function bindPaste() {
        var doc;
        try {
            doc = editor.getDoc();
        } catch (e) {
            return;
        }
        if (!doc || doc.__synoMdBound) {
            return;
        }
        doc.__synoMdBound = true;
        // 捕获阶段绑定：必须早于 syno_paste 的冒泡监听，否则内容已被它插入
        doc.addEventListener('keydown', onKeyDownCapture, true);
        doc.addEventListener('paste', onPasteCapture, true);
    }

    if (editor.initialized) {
        bindPaste();
    } else {
        editor.on('init', bindPaste);
    }

    // =====================================================================
    //  五、工具栏开关
    // =====================================================================

    // 工具栏图标：内联 SVG，两种配色对应开关状态（深色 = 已开启，浅色 = 已关闭）
    var ICON_URI_MD_ON = 'data:image/svg+xml;base64,';
    var ICON_URI_MD_OFF = 'data:image/svg+xml;base64,';

    function applyIcon(btn, uri) {
        try {
            var el = btn && btn.getEl && btn.getEl();
            if (!el) { return; }
            var ico = el.querySelector ? el.querySelector('.mce-ico') : null;
            if (!ico) {
                // 兜底：控件没生成图标节点时自己补一个，宽度与原生图标按钮一致
                var host = (el.querySelector && el.querySelector('button')) || el;
                ico = (el.ownerDocument || document).createElement('i');
                ico.className = 'mce-ico';
                host.insertBefore(ico, host.firstChild);
            }
            ico.style.backgroundImage = 'url("' + uri + '")';
            ico.style.backgroundSize = '20px 20px';
            ico.style.backgroundPosition = 'center center';
            ico.style.backgroundRepeat = 'no-repeat';
        } catch (err) { /* ignore */ }
    }

    // 当前编辑器实例的按钮引用，用于按开关状态切换图标配色
    var mdButton = null;

    /**
     * 按当前 enabled 状态同步工具栏图标配色。
     * 开启为深色，关闭为浅灰，便于一眼看出转换是否生效。
     */
    function syncIcon() {
        if (mdButton) {
            applyIcon(mdButton, enabled ? ICON_URI_MD_ON : ICON_URI_MD_OFF);
        }
    }

    editor.addButton('syno_markdown', {
        icon: 'none',
        image: ICON_URI_MD_ON,
        tooltip: 'Markdown 输入 / 粘贴转换：开 / 关',
        onclick: function () {
            enabled = !enabled;
            persist();
            this.active(enabled);
            syncIcon();
            editor.focus();
        },
        onPostRender: function () {
            mdButton = this;
            this.active(enabled);
            syncIcon();
        }
    });
});
